                    ? PlatformServices.UnprotectData(encryptedBytes, Entropy)
                    : DecryptFallback(encryptedBytes);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Failed to decrypt: {ex.Message}");
                return string.Empty;
            }
        }

        return value;
